text:
JWT `exp` in **seconds**. `Date.now()` in **milliseconds**.

**Bug:**
```js
if (Date.now() > payload.exp) // wrong — always false, exp looks huge
```

**Fix:**
```js
if (Date.now() / 1000 > payload.exp) // convert ms → s
// or
if (Math.floor(Date.now() / 1000) > payload.exp)
```

**Full middleware:**
```js
function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token' });

  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    // jwt.verify already checks expiry — but if manual:
    if (Math.floor(Date.now() / 1000) > payload.exp) {
      return res.status(401).json({ error: 'Token expired' });
    }
    req.user = payload;
    next();
  } catch (err) {
    res.status(401).json({ error: 'Invalid token' });
  }
}
```

Side note: `jwt.verify()` from `jsonwebtoken` lib check expiry auto. Manual check redundant unless using raw decode. Use `jwt.verify` → skip manual check entirely.
